import{_ as a,o as t,c as s,ag as i}from"./chunks/framework.DXGyWiRo.js";const p=JSON.parse('{"title":"Summarization","description":"Enable conversation summarization for long sessions to stay within model context limits.","frontmatter":{"title":"Summarization","description":"Enable conversation summarization for long sessions to stay within model context limits."},"headers":[],"relativePath":"guides/summarization.md","filePath":"guides/summarization.md"}'),o={name:"guides/summarization.md"};function n(r,e,l,d,h,c){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="summarization" tabindex="-1">Summarization <a class="header-anchor" href="#summarization" aria-label="Permalink to &quot;Summarization&quot;">​</a></h1><p>DOAI Proxy can automatically summarize older messages in long conversations to stay within a model&#39;s context limit. This is useful for extended sessions where the conversation history grows beyond what the model can handle.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>When enabled, the proxy estimates input tokens from the message history. If the estimated tokens exceed a percentage of the model&#39;s context limit:</p><ol><li>Older messages are replaced with a concise summary</li><li>Recent messages are kept verbatim</li><li>System messages are always preserved</li></ol><p>The summarization is done by making a separate API call to the provider, asking it to summarize the conversation history.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>SUMMARIZATION_ENABLED</code></td><td>Enable conversation summarization</td><td><code>false</code></td></tr><tr><td><code>SUMMARIZATION_THRESHOLD_PCT</code></td><td>Percentage of context limit that triggers summarization</td><td><code>70</code></td></tr><tr><td><code>SUMMARIZATION_KEEP_MESSAGES</code></td><td>Number of recent messages to keep verbatim</td><td><code>10</code></td></tr><tr><td><code>SUMMARIZATION_MODEL</code></td><td>Model for summarization. <code>&quot;auto&quot;</code> uses smart_llm_selector</td><td><code>auto</code></td></tr><tr><td><code>SUMMARIZATION_TIMEOUT</code></td><td>Timeout in ms for summarization API calls</td><td><code>15000</code></td></tr></tbody></table><h2 id="enabling-summarization" tabindex="-1">Enabling Summarization <a class="header-anchor" href="#enabling-summarization" aria-label="Permalink to &quot;Enabling Summarization&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Enable summarization</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SUMMARIZATION_ENABLED</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Trigger when input exceeds 70% of model context</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SUMMARIZATION_THRESHOLD_PCT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">70</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Keep the last 10 messages verbatim</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SUMMARIZATION_KEEP_MESSAGES</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">10</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Use auto model selection for summarization</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SUMMARIZATION_MODEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">auto</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Timeout after 15 seconds</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SUMMARIZATION_TIMEOUT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">15000</span></span></code></pre></div><h2 id="threshold-percentage" tabindex="-1">Threshold Percentage <a class="header-anchor" href="#threshold-percentage" aria-label="Permalink to &quot;Threshold Percentage&quot;">​</a></h2><p>The <code>SUMMARIZATION_THRESHOLD_PCT</code> controls when summarization kicks in:</p><ul><li><strong>Lower values</strong> (e.g., 50): More aggressive summarization, triggers sooner</li><li><strong>Higher values</strong> (e.g., 85): Less aggressive, only triggers when context is nearly full</li><li><strong>Default (70)</strong>: Good balance between context utilization and summarization frequency</li></ul><p>Input tokens are estimated as <code>JSON.stringify(messages).length / 3.5</code>. The proxy compares <code>estimatedTokens + outputTokens</code> against <code>model.word_limit * (threshold / 100)</code>.</p><h2 id="model-selection" tabindex="-1">Model Selection <a class="header-anchor" href="#model-selection" aria-label="Permalink to &quot;Model Selection&quot;">​</a></h2><p>The <code>SUMMARIZATION_MODEL</code> setting determines which model generates summaries:</p><ul><li><strong><code>auto</code></strong> (default): Uses Straico&#39;s <code>smart_llm_selector</code> with <code>pricing_method: &quot;balance&quot;</code> for automatic, cost-optimized model selection</li><li><strong>Specific model ID</strong>: Use any supported model (e.g., <code>meta-llama/llama-3.1-8b-instruct</code>)</li></ul><p>Using a smaller, faster model for summarization can reduce cost while still producing useful summaries.</p><h2 id="timeout-behavior" tabindex="-1">Timeout Behavior <a class="header-anchor" href="#timeout-behavior" aria-label="Permalink to &quot;Timeout Behavior&quot;">​</a></h2><p>If the summarization API call exceeds <code>SUMMARIZATION_TIMEOUT</code> (default 15 seconds), the proxy falls back to sending the original, unsummarized messages. This ensures the conversation continues even if summarization fails or times out.</p><h2 id="what-gets-preserved" tabindex="-1">What Gets Preserved <a class="header-anchor" href="#what-gets-preserved" aria-label="Permalink to &quot;What Gets Preserved&quot;">​</a></h2><ul><li><strong>System messages</strong>: Always preserved verbatim, never summarized</li><li><strong>Recent messages</strong>: The last <code>SUMMARIZATION_KEEP_MESSAGES</code> messages (default 10) are kept verbatim</li><li><strong>Older messages</strong>: Replaced with a summary</li></ul><h2 id="context-validation" tabindex="-1">Context Validation <a class="header-anchor" href="#context-validation" aria-label="Permalink to &quot;Context Validation&quot;">​</a></h2><p>The proxy also validates total context independently of summarization. If input tokens + output tokens exceed the model&#39;s limit, the request is rejected with a <code>400</code> error. Summarization helps prevent this from happening by reducing the input size proactively.</p><p>See <a href="/guides/configuration">Configuration</a> for all environment variables and <a href="/api/error-codes">Error Codes</a> for context validation errors.</p>`,25)])])}const u=a(o,[["render",n]]);export{p as __pageData,u as default};
